/**
 * Test case for https://issues.apache.org/jira/browse/ZOOKEEPER-2380.
 * Deadlock while shutting down the ZooKeeper
 */
@Test
@Timeout(value = 30)
public void testRaceConditionBetweenLeaderAndAckRequestProcessor() throws Exception {
    mt = startQuorum();
    // get leader
    QuorumPeer leader = getLeader(mt);
    long oldLeaderCurrentEpoch = leader.getCurrentEpoch();
    assertNotNull(leader, "Leader should not be null");
    // shutdown 2 followers so that leader does not have majority and goes
    // into looking state or following/leading state.
    shutdownFollowers(mt);
    /**
     * <pre>
     * Verify that there is no deadlock in following ways:
     * 1) If leader is in LOOKING or FOLLOWING, we are sure there is no deadlock.
     * 2) If leader in in LEADING state then we have to check that this LEADING state is
     * after the leader election, not the old LEADING state.
     * </pre>
     */
    boolean leaderStateChanged = ClientBase.waitForServerState(leader, 15000, QuorumStats.Provider.LOOKING_STATE, QuorumStats.Provider.FOLLOWING_STATE);
    // Wait for the old leader to start completely
    assertTrue(ClientBase.waitForServerUp("127.0.0.1:" + leader.getClientPort(), CONNECTION_TIMEOUT), "Failed to bring up the old leader server");
    assertTrue(leaderStateChanged || (leader.getCurrentEpoch() > oldLeaderCurrentEpoch), "Leader failed to transition to new state. Current state is " + leader.getServerState());
}

/**
 * test method {@link ZooKeeperServer#processConnectRequest(org.apache.zookeeper.server.ServerCnxn, java.nio.ByteBuffer)}
 */
@Test
public void testReadOnlyZookeeperServer() {
    ReadOnlyZooKeeperServer readOnlyZooKeeperServer = new ReadOnlyZooKeeperServer(mock(FileTxnSnapLog.class), mock(QuorumPeer.class), mock(ZKDatabase.class));
    final ByteBuffer output = ByteBuffer.allocate(30);
    // serialize a connReq
    output.putInt(1);
    output.putLong(1L);
    output.putInt(500);
    output.putLong(123L);
    output.putInt(1);
    output.put((byte) 1);
    // set readOnly false
    output.put((byte) 0);
    output.flip();
    ServerCnxn.CloseRequestException e = assertThrows(ServerCnxn.CloseRequestException.class, () -> {
        final NIOServerCnxn nioServerCnxn = mock(NIOServerCnxn.class);
        readOnlyZooKeeperServer.processConnectRequest(nioServerCnxn, output);
    });
    assertEquals(e.getReason(), ServerCnxn.DisconnectReason.NOT_READ_ONLY_CLIENT);
}

