public void testCircularBuffer() {
    final int capacity = 3;
    CircularBuffer<String> buffer = new CircularBuffer<>(String.class, capacity);
    assertTrue(buffer.isEmpty());
    assertFalse(buffer.isFull());
    // write to the buffer
    buffer.write("A");
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    buffer.write("B");
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    buffer.write("C");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // Buffer is full.
    // Read from buffer
    assertEquals("A", buffer.take());
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    assertEquals("B", buffer.take());
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    assertEquals("C", buffer.take());
    assertTrue(buffer.isEmpty());
    assertFalse(buffer.isFull());
    // write to the buffer
    buffer.write("1");
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    buffer.write("2");
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    buffer.write("3");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // 4 overwrites 1
    buffer.write("4");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // Buffer if full
    // Read from buffer
    assertEquals("2", buffer.take());
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    assertEquals("3", buffer.take());
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    assertEquals("4", buffer.take());
    assertTrue(buffer.isEmpty());
    assertFalse(buffer.isFull());
    // write to the buffer
    buffer.write("a");
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    buffer.write("b");
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    buffer.write("c");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // d overwrites a
    buffer.write("d");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // e overwrites b
    buffer.write("e");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // f overwrites c
    buffer.write("f");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // g overwrites d
    buffer.write("g");
    assertFalse(buffer.isEmpty());
    assertTrue(buffer.isFull());
    // Buffer is full.
    // Read from buffer
    assertEquals("e", buffer.take());
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    assertEquals("f", buffer.take());
    assertFalse(buffer.isEmpty());
    assertFalse(buffer.isFull());
    assertEquals("g", buffer.take());
    assertTrue(buffer.isEmpty());
    assertFalse(buffer.isFull());
}

