@Test
public void testMultiThreadPerf() throws InterruptedException {
    RequestPathMetricsCollector requestPathMetricsCollector = new RequestPathMetricsCollector();
    Random rand = new Random(System.currentTimeMillis());
    Long startTime = System.currentTimeMillis();
    ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newCachedThreadPool();
    //call 100k get Data
    for (int i = 0; i < 100000; i++) {
        executor.submit(() -> requestPathMetricsCollector.registerRequest(getData, "/path1/path2/path" + rand.nextInt(10)));
    }
    //5K create
    for (int i = 0; i < 5000; i++) {
        executor.submit(() -> requestPathMetricsCollector.registerRequest(create2, "/path1/path2/path" + rand.nextInt(10)));
    }
    //5K delete
    for (int i = 0; i < 5000; i++) {
        executor.submit(() -> requestPathMetricsCollector.registerRequest(delete, "/path1/path2/path" + rand.nextInt(10)));
    }
    //40K getChildren
    for (int i = 0; i < 40000; i++) {
        executor.submit(() -> requestPathMetricsCollector.registerRequest(getChildren, "/path1/path2/path" + rand.nextInt(10)));
    }
    executor.shutdown();
    //wait for at most 10 mill seconds
    executor.awaitTermination(10, TimeUnit.MILLISECONDS);
    assertTrue(executor.isTerminated());
    Long endTime = System.currentTimeMillis();
    //less than 2 seconds total time
    assertTrue(TimeUnit.MILLISECONDS.toSeconds(endTime - startTime) < 3);
}

