@Test
public void testRecursiveQtyConcurrency() {
    ThreadLocalRandom random = ThreadLocalRandom.current();
    WatcherModeManager manager = new WatcherModeManager();
    ExecutorService threadPool = Executors.newFixedThreadPool(clientQty);
    List<Future<?>> tasks = null;
    CountDownLatch completedLatch = new CountDownLatch(clientQty);
    try {
        tasks = IntStream.range(0, clientQty).mapToObj(__ -> threadPool.submit(() -> iterate(manager, completedLatch))).collect(Collectors.toList());
        try {
            completedLatch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    } finally {
        if (tasks != null) {
            tasks.forEach(t -> t.cancel(true));
        }
        threadPool.shutdownNow();
    }
    int expectedRecursiveQty = (int) manager.getWatcherModes().values().stream().filter(mode -> mode == WatcherMode.PERSISTENT_RECURSIVE).count();
    assertEquals(expectedRecursiveQty, manager.getRecursiveQty());
}

@Test
public void testProcessDeadWatchersBasedOnThreshold() {
    MyDeadWatcherListener listener = new MyDeadWatcherListener();
    int threshold = 3;
    WatcherCleaner cleaner = new WatcherCleaner(listener, threshold, 60, 1, 10);
    cleaner.start();
    int i = 0;
    while (i++ < threshold - 1) {
        cleaner.addDeadWatcher(i);
    }
    // not trigger processDeadWatchers yet
    assertEquals(0, listener.getDeadWatchers().size());
    listener.setCountDownLatch(new CountDownLatch(1));
    // add another dead watcher to trigger the process
    cleaner.addDeadWatcher(i);
    assertTrue(listener.wait(1000));
    assertEquals(threshold, listener.getDeadWatchers().size());
}

