        for (int i = 0; i < 10; i++) {
            zkWatchCreator.create("/" + i, new byte[0], Ids.OPEN_ACL_UNSAFE, CreateMode.PERSISTENT);
        }
        for (int i = 0; i < 10; i++) {
            zkIdle.exists("/" + i, true);
