        for (int i = 0; i < 10; i++) {
            Thread.sleep(1000);
            zkWatchCreator.delete("/" + i, -1);
        }
        // The bug will manifest itself here because zkIdle will expire
        zkIdle.exists("/0", false);
    } finally {
        if (zkIdle != null) {
            zkIdle.close();
        }
        if (zkWatchCreator != null) {
            zkWatchCreator.close();
        }
    }
}

