@Test
public void testBasicCreateMode() {
    CreateMode cm = CreateMode.PERSISTENT;
    assertEquals(cm.toFlag(), 0);
    assertFalse(cm.isEphemeral());
    assertFalse(cm.isSequential());
    assertFalse(cm.isContainer());
    cm = CreateMode.EPHEMERAL;
