/**
 * Make sure that we can change sessions
 *  from follower to leader.
 *
 * @throws IOException
 * @throws InterruptedException
 * @throws KeeperException
 */
@Test
public void testSessionMoved() throws Exception {
    String[] hostPorts = qb.hostPort.split(",");
    DisconnectableZooKeeper zk = new DisconnectableZooKeeper(hostPorts[0], ClientBase.CONNECTION_TIMEOUT, DummyWatcher.INSTANCE);
    zk.create("/sessionMoveTest", new byte[0], Ids.OPEN_ACL_UNSAFE, CreateMode.EPHEMERAL);
    // we want to loop through the list twice
    for (int i = 0; i < hostPorts.length * 2; i++) {
        zk.dontReconnect();
        // This should stomp the zk handle
        DisconnectableZooKeeper zknew = new DisconnectableZooKeeper(hostPorts[(i + 1) % hostPorts.length], ClientBase.CONNECTION_TIMEOUT, DummyWatcher.INSTANCE, zk.getSessionId(), zk.getSessionPasswd());
        zknew.setData("/", new byte[1], -1);
        final int[] result = new int[1];
        result[0] = Integer.MAX_VALUE;
        zknew.sync("/", (rc, path, ctx) -> {
            synchronized (result) {
                result[0] = rc;
                result.notify();
            }
        }, null);
        synchronized (result) {
            if (result[0] == Integer.MAX_VALUE) {
                result.wait(5000);
            }
        }
        LOG.info("{} Sync returned {}", hostPorts[(i + 1) % hostPorts.length], result[0]);
        assertTrue(result[0] == KeeperException.Code.OK.intValue());
        try {
            zk.setData("/", new byte[1], -1);
            fail("Should have lost the connection");
        } catch (KeeperException.ConnectionLossException e) {
        }
        zk = zknew;
    }
    zk.close();
}

